INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('bouquet-happy-tulip','Bouquet Happy Tulip','Bouquet Happy Tulip es un ramo vibrante y elegante creado para esos momentos en los que un gesto merece verse grande. Su composición de 60 tulipanes premium reúne color, frescura y presencia en un detalle pensado para celebrar, agradecer o sorprender de una forma distinta. Es ideal para cumpleaños, aniversarios, celebraciones especiales o para recordarle a alguien que está presente en tu vida con un gesto lleno de color y significado. DESCRIPCIÓN: Ramo de 60 tulipanes premium. ( Los colores varían según disponibilidad: blanco, amarillo, rosado, rojo, naranja, fucsia y morado ) Empaque especial y único. Imagen referencial, puede variar ligeramente de acuerdo a estación de flores secundarias. Producto exclusivo de Magia.pe Ten en cuenta: Como cada tallo es único en sus características, los colores o las flores utilizadas pueden variar respecto a las de la foto.','Tulipanes','580.00','/images/bouquet-happy-tulip.webp','1','1','1','https://magia.pe/products/bouquet-happy-tulip');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('bouquet-pack','Bouquet Pack','El Bouquet Pack es una forma cálida de celebrar y compartir. Combina un ramo de 12 rosas con un queque de zanahoria, creando un detalle ideal para cumpleaños, felicitaciones, graduaciones, agradecimientos o momentos en los que quieres estar presente con algo especial. Es un regalo pensado para convertir una emoción en una acción sencilla, cercana y memorable: llegar con flores y el complemento perfecto, con un delicioso queque de zanahoria, decorado con frosting de queso crema y pecanas. DESCRIPCIÓN: Ramo de 12 rosas y verdes de acuerdo a disponibilidad Empaque único y especial 1 Queque de zanahoria rectangular, decorado con frosting de queso quema y pecanas. Rinde 8 porciones aproximadamente Imagen referencial, puede variar ligeramente Producto exclusivo de Magia.pe ® Ten en cuenta: Como cada tallo es único en sus características, los colores o las flores utilizadas pueden variar respecto a las de la foto.','Ramos','160.00','/images/bouquet-pack.webp','1','1','1','https://magia.pe/products/bouquet-pack');
