INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-de-lirios','Box De Lirios','La elegancia y la pureza se unen en este sofisticado arreglo floral premium. Su diseño armonioso transmite paz, admiración y buenos deseos, convirtiéndolo en el regalo perfecto para celebrar momentos especiales o expresar sentimientos sinceros. Arreglos de Lirios premium acompañados de claveles y mix de follaje Dimensiones de la caja: 25 cm x 5 cm / el alto se incrementa con el tamaño de las flores. Box Magia.pe ® Imagen referencial, puede variar ligeramente Producto exclusivo de Magia.pe ® TEN EN CUENTA: Cada flor es única. Pueden presentar ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño prémium característico de Magia.pe®','Rosas y arreglos','220.00','/images/box-de-lirios.webp','1','1','0','https://magia.pe/products/box-de-lirios');
