INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-elise-royale','Box Elisé Royale','DESCRIPCIÓN: El Box “Elisé Royale” es un tributo a la elegancia y la dulzura. Un arreglo floral premium diseñado para transmitir amor, gratitud y sofisticación en cada detalle. Compuesto por un bello mix de 75 flores premium , combina rosas melón, rosas palo de rosa y rosas pink mundial , acompañadas de claveles rosados, lisianthus y mini rosas en tonos rosados y fucsias , formando una composición armoniosa, fresca y delicada. Presentado en un box rosado con acabado elegante y lazo decorativo , IDEAL PARA: Es el regalo perfecto para expresar amor, celebrar aniversarios o sorprender con un detalle que deslumbra, con la calidad y frescura que distinguen a Magia.pe® . Disponible con delivery el mismo día en Lima y Callao. IMPORTANTE: Cada flor es única. Pueden presentarse ligeras variaciones en color o forma respecto a la imagen referencial, manteniendo siempre la belleza, frescura y calidad artesanal de Magia.pe®.','Rosas y arreglos','680.00','/images/box-elise-royale.webp','1','1','0','https://magia.pe/products/box-elise-royale');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-eloise-chic','Box Eloise Chic','El Box Eloise Chic de Magia.pe® reúne una armoniosa combinación de mix de 30 entre rosas rojas, rosas pink mundial, claveles rojos y mini rosas rosadas , complementadas con eucalipto fresco y caspia guinda . Su diseño elegante y romántico lo convierte en el detalle perfecto para regalar en cumpleaños, aniversarios, celebraciones especiales o simplemente para engreír de una forma inolvidable IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño prémium característico de Magia.pe® .','Rosas y arreglos','210.00','/images/box-eloise-chic.webp','1','1','0','https://magia.pe/products/box-eloise-chic');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-eres-magia','Box \"Eres Magia\"','12 rosas prémium en tonos rosados 10 tulipanes tiernos Flores secundarias entre mini rosa y hortensias en tonos rosados (el tono de rosado puede variar de acuerdo a disponibilidad) Dimensiones del box: 15cm x 15cm / el alto se incrementa con el tamaño de las flores. Imagen referencial, puede variar de acuerdo a disponibilidad Producto exclusivo de Magia.pe® El arreglo está elaborado con rosas Pink Mondial , está variedad de rosa tiene como característica presentar un color verde - amarillo ligero en los bordes. Es una rosa maravillosa y de gran apertura, propia de su naturaleza.','Rosas y arreglos','335.00','/images/box-eres-magia.webp','1','1','1','https://magia.pe/products/box-eres-magia');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-eternal-pink','Box Eternal Pink','El Box Eternal Pink combina flores secas en una composición elegante y sofisticada, es un detalle delicado y atemporal, perfecto para engreírla. Este arreglo combina cardos blancos, jaspia en tonos rosados y blancos, pica piedra rosa y margaritas rosadas, logrando una paleta suave y delicada. Se complementa con la textura de la cola de conejo, la sutileza de la gipsophilia blanca y el toque natural del eucalipto, junto a las rosas lunarias que aportan un acabado especial y duradero IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño premium característico de Magia.pe®.','Rosas y arreglos','165.00','/images/box-eternal-pink.webp','1','1','1','https://magia.pe/products/box-eternal-pink');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-eternal-sun','Box Eternal Sun','Hay gestos que permanecen mucho después de haberlos recibido. Box Eternal Sun es una composición de flores secas en tonos amarillos y rosados, creada para regalar este 21 de septiembre de una manera diferente. Sus rosas, lunarias y delicados acompañamientos forman un detalle que puede conservarse en el tiempo como recuerdo de un momento y de una persona especial. Una forma de regalar flores amarillas con significado, porque los vínculos importantes se construyen gesto a gesto.','Rosas y arreglos','150.00','/images/box-eternal-sun.webp','1','1','0','https://magia.pe/products/box-eternal-sun');
