INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-love','Box Love','El Box Love es un gesto pensado para hacer sentir importante a alguien especial. Su composición de 24 flores premium equilibra diseño, emoción y presencia en una presentación delicada, ideal para cumpleaños, amor, agradecimiento o cualquier momento en el que quieras convertir lo que sientes en una acción. Más que un arreglo floral, es una forma de aparecer, demostrar y crear un recuerdo especial con una persona que importa. Detalles del producto Mix de 24 flores súper premium Box Magia.pe con frase “Eres Magia” o \"Logo Magia\" Dimensiones aproximadas del box: 15 cm x 15 cm (La altura total varía según el tamaño natural de las flores) Producto exclusivo de Magia.pe® Importante Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial. Estas variaciones no afectan la cantidad, frescura, calidad ni el diseño prémium característico de Magia.pe® .','Rosas y arreglos','199.00','/images/box-love.webp','1','1','0','https://magia.pe/products/box-love');
