INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-pink-bliss','Box Pink Bliss','Arreglo premium de flores secas en una composición elegante y sofisticada, es un detalle delicado y atemporal, perfecto para engreírla. Este arreglo combina rosas lunareas, algodon, jaspia en tonos rosados y blancos, margaritas blancas, logrando una paleta suave y delicada. Se complementa con la textura de la cola de conejo, la sutileza de la gipsophilia blanca y el toque natural del eucalipto, junto a las rosas lunarias que aportan un acabado especial y duradero IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño premium característico de Magia.pe®.','Rosas y arreglos','175.00','/images/box-pink-bliss.webp','1','1','0','https://magia.pe/products/box-pink-bliss');
