INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-ruby','Box Ruby','El Box Ruby de Magia.pe® es un arreglo floral sofisticado compuesto por 36 rosas rojas premium , acompañadas de orquídeas blancas y follaje de acompañamiento, que aportan contraste y elegancia a la composición. Presentado en un box exclusiva en tono rojo terciopleado , este arreglo es perfecto para expresar amor, admiración o pasión en ocasiones especiales. Descripción: 36 rosas premium rojas acompañados de follaje verde de estación 2 Orquídeas blancas ( color puede variar de acuerdo a disponibilidad, siempre cuidando la armonía) Producto exclusivo de Magia.pe ® IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño prémium característico de Magia.pe® .','Rosas y arreglos','265.00','/images/box-ruby.webp','1','1','0','https://magia.pe/products/box-ruby');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-scarlet-bloom','Box Scarlet Bloom','Un regalo que equilibra diseño, emoción y presencia. El Box Love San Valentín está creado para emocionar de verdad , con una composición romántica y armoniosa que convierte cualquier momento en un recuerdo especial. Este arreglo reúne un mix de 24 flores súper premium , cuidadosamente seleccionadas por su frescura, color y calidad superior, presentadas en un box guinda terciopelado exclusivo Magia.pe con la frase “Eres Magia” . Un diseño elegante y contemporáneo, pensado para decir te elijo de una forma auténtica y memorable. No es solo un box floral: es un gesto que se siente, sorprende y deja huella. Ideal para San Valentín y para quienes buscan una florería premium en Lima que garantice un wow real desde el primer instante. Disfruta de nuestro servicio de envío de flores a domicilio en Lima , rápido, seguro y puntual, para que tu regalo llegue perfecto y con la emoción intacta. Detalles del producto Mix de 24 flores súper premium Box guinda terciopelado Magia.pe con frase “Eres Magia” Dimensiones aproximadas del box: 15 cm x 20 cm (la altura total varía según el tamaño natural de las flores) Producto exclusivo de Magia.pe® Importante Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial. Estas variaciones no afectan la cantidad, frescura, calidad ni el diseño premium característico de Magia.pe® .','Rosas y arreglos','185.00','/images/box-scarlet-bloom.webp','1','1','0','https://magia.pe/products/box-scarlet-bloom');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-scarlet-elegance','Box Scarlet Elegance','El box Scarlet Elegance de Magia.pe® reúne 12 rosas rojas premium y 15 claveles rojos seleccionados, complementados con follaje silver dollar que aporta frescura y un contraste sofisticado. Una composición intensa y elegante, diseñada para declarar amor, expresar admiración o celebrar momentos que merecen un gesto verdaderamente inolvidable. IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño prémium característico de Magia.pe® .','Rosas y arreglos','180.00','/images/box-scarlet-elegance.webp','1','1','0','https://magia.pe/products/box-scarlet-elegance');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-soleil','Box Soleil','Box Soleil reúne diferentes flores en tonos amarillos, lilas y naranjas, con girasoles como protagonistas, creando una composición llena de color y vida. Una opción especial para este 21 de septiembre , porque regalar flores amarillas también es una forma de decir “pensé en ti” y seguir construyendo relaciones importantes, gesto a gesto. Medida aprox: 45cm','Rosas y arreglos','590.00','/images/box-soleil.webp','1','1','0','https://magia.pe/products/box-soleil');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-suena-en-grande','Box \"Sueña en Grande\"','Celebra los grandes logros con este arreglo floral premium , creado para transmitir orgullo, alegría y elegancia en cada detalle. Compuesto por 30 flores premium compuestos por una variedad de rosas en tonos rosados , claveles selectos y mini rosas en tonos fucsia , y delicados acentos de statis lila , forma una composición equilibrada, fresca y encantadora. Su diseño se realza con un abanico decorativo que aporta un toque artístico y festivo, presentado en un box rosa perlado con acabados de lujo . El regalo perfecto para celebrar una graduación , expresar amor, gratitud o reconocer esfuerzo y éxito con la elegancia que distingue a Magia.pe® . Disponible con delivery el mismo día en Lima y Callao. Importante: Cada flor es única. Pueden presentarse ligeras variaciones en color o forma respecto a la imagen referencial, manteniendo siempre la belleza, frescura y calidad artesanal de Magia.pe® .','Rosas y arreglos','290.00','/images/box-suena-en-grande.webp','1','1','0','https://magia.pe/products/box-suena-en-grande');
