INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('box-tulip-sun','Box Tulip Sun','Box Tulip Sun reúne 20 tulipanes en una composición llena de color y delicadeza, creada para celebrar este 21 de septiembre de una manera diferente. Regalar tulipanes es un gesto asociado al cariño, los buenos deseos y el afecto sincero, convirtiéndolos en una forma especial de recordarle a alguien cuánto significa para ti. Porque las relaciones importantes también se construyen gesto a gesto. Incluye: 20 tulipanes premium Box premium Magia.pe Importante: Los colores de los tulipanes se seleccionan de acuerdo con la disponibilidad de stock. La combinación puede variar respecto a la fotografía referencia','Tulipanes','295.00','/images/box-tulip-sun.webp','0','1','0','https://magia.pe/products/box-tulip-sun');
