INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('gift-box-signature','Gift Box Signature','Un gift box premium que reúne un osito de textura suave, acompañado de complementos cuidadosamente seleccionados para regalar en San Valentín. Un detalle pensado para sorprender y expresar lo que llevas en el corazón. Descripción: Osito peluche Matt ( 60 cm aprox) Taza Magia con frase \" Te amo, lo digo enserio\" Jar de mini alfajores en forma de corazón Mini torta red velvet Ramo small de flores secas ( color de acuerdo a stock) IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño prémium característico de Magia.pe® .','Rosas y arreglos','235.00','/images/gift-box-signature.webp','1','1','0','https://magia.pe/products/gift-box-signature');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('gift-box-special','Corp Magia 60','Sorprende con una elegante selección de productos gourmet cuidadosamente presentados. Ideal para regalar en ocasiones especiales como Día de Padre , celebraciones corporativas o para disfrutar momentos únicos en compañía. DESCRIPCIÓN: Tabla de picar con mango 27 x15cm aprox. Pitacrips Coctel Tabla Gourmet 100g Chocolate Ferrero de 3 unidades Dip de Espárrago Verde Casa Verde 285g Frasco de frutos secos Queso Duro Manchego Baby Maese Miguel Barra 200 gr. Ramo Small con flores de estación / Variación de acuerdo a requerimiento. Imagen referencial, puede variar ligeramente de acuerdo a stock. Producto exclusivo de Magia.pe ®','Regalos','205.00','/images/gift-box-special.webp','1','1','0','https://magia.pe/products/gift-box-special');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('gift-box-sunrise','Gift Box Sunrise','Un Gift box premium con girasoles y un mini cake, la combinación ideal para regalar y sorprender a la persona que tienes en el corazón. Descripción: Un mix de girasoles super premium. Mini torta (Chocolate, Carrot cake o Red velvet) de acuerdo a disponibilidad de stock IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño premium característico de Magia.pe® . Entrega inmediata en Lima y Callao.','Rosas y arreglos','170.00','/images/gift-box-sunrise.webp','1','1','0','https://magia.pe/products/gift-box-sunrise');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('gift-box-sweet-charlotte','Gift Box Sweet Charlotte','El Gift Box Sweet Charlotte es un gesto dulce y memorable para hacer sentir importante a alguien especial. Combina flores, peluche, mini torta y una bebida en una presentación pensada para sorprender desde el primer momento. Es ideal para cumpleaños o para esos días en los que quieres convertir lo que sientes en una acción concreta: aparecer, demostrar cariño y crear un recuerdo que esa persona pueda guardar. DESCRIPCIÓN: 1 Osito de peluche ( aprox. 60cm alto) 1 Mini torta carrot cake o mini red velvet Arreglo premium con 12 mix de flores entre rosas y claveles Starbucks Frappuccino 281ml . Imagen referencial, puede variar ligeramente de acuerdo a estación de flores secundarias. Producto exclusivo de Magia.pe IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño premium característico de Magia.pe® .','Rosas y arreglos','330.00','/images/gift-box-sweet-charlotte.webp','1','1','0','https://magia.pe/products/gift-box-sweet-charlotte');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('gift-box-sweet-love','Gift Box Sweet Love','Un gift box floral prémium que combina rosas y mini rosas en una composición delicada y equilibrada, acompañado de unos deliciosos postres cuidadosamente seleccionados. El regalo perfecto para San Valentín, presentado en el exclusivo box Magia.pe. Descripción: Mix de flores y follaje en petit box rosado. Taza Magia con frase \"Te amo, lo digo enserio\" Mini torta red velvet Jar de mini alfajores en forma de corazón IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño prémium característico de Magia.pe® .','Rosas y arreglos','160.00','/images/gift-box-sweet-love.webp','1','1','0','https://magia.pe/products/gift-box-sweet-love');
