INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('majestic-velvet-sunflower','Majestic velvet sunflower','Hay gestos que dicen mucho y otros que simplemente lo dicen todo. Este impresionante arreglo reúne aproximadamente 100 girasoles , cuidadosamente seleccionados y dispuestos en nuestra elegante caja Magia.pe para crear una composición llena de luz, energía y presencia. Diseñado para sorprender a lo grande, es el regalo perfecto para celebrar cumpleaños, aniversarios, logros o simplemente para recordarle a alguien lo importante que es. Porque cuando la ocasión —o la persona— lo merece, un pequeño detalle no siempre es suficiente','Regalos','700.00','/images/majestic-velvet-sunflower.webp','1','1','0','https://magia.pe/products/majestic-velvet-sunflower');
INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('majetic-red-velvet','Majestic Red Velvet – Magia.pe','Una pieza floral que trasciende lo convencional. Este box floral de gran formato pertenece a la colección más lujosa de Magia.pe , creada para quienes buscan un regalo impactante, sofisticado y absolutamente inolvidable . La composición reúne un mix de aproximadamente 150 flores premium , cuidadosamente seleccionadas entre rosas, claveles, mini rosas y lisianthus , combinadas con verdes de estación que aportan profundidad, textura y equilibrio visual. Cada arreglo es diseñado a mano, respetando una estética elegante y contemporánea, pensada para provocar un wow inmediato . No es solo un box floral: es una declaración de presencia, abundancia y buen gusto. Ideal para celebraciones extraordinarias, momentos icónicos o cuando el gesto debe hablar por sí solo. Disfruta de nuestro servicio de envío de flores de lujo a domicilio en Lima , con entrega cuidada, puntual y a la altura de una experiencia premium. Detalles del producto Aprox. 150 flores premium (mix de rosas, claveles, mini rosas y lisianthus — puede variar según disponibilidad) Verdes de estación seleccionados , según disponibilidad Dimensiones aproximadas del box: 40 cm x 20 cm (la altura total se incrementa con el tamaño natural de las flores) Producto exclusivo de Magia.pe® Importante Cada flor es única. Pueden presentarse ligeras variaciones respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño premium característico de Magia.pe® .','Regalos','1010.00','/images/majetic-red-velvet.webp','1','1','0','https://magia.pe/products/majetic-red-velvet');
