INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('pack-magia-pe-love','Pack Magia.pe Love','Pack Magia.pe – Flores Premium + Cookies Artesanales Engríe a esa persona especial con el Pack Magia.pe Love , una experiencia diseñada para emocionar de verdad y provocar un wow inolvidable . Este regalo combina un ramo de rosas y flores mixtas premium , en colores vibrantes y cuidadosamente seleccionados, con cookies artesanales elaboradas con mantequilla y trozos de delicioso chocolate, creando un match perfecto entre belleza y sabor. Disfruta de nuestro servicio de envío de flores y regalos a domicilio en Lima. Descripción del producto Mix de flores premium : rosas, claveles seleccionados y follaje de estación Caja de 6 cookies artesanales a base de mantequilla con trozos de delicioso chocolate Dimensiones aproximadas del ramo : 60 cm de alto x 17.5 cm de ancho Incluye tarjeta con sobre de papel fino No incluye florero IMPORTANTE Cada flor es única. Pueden presentarse ligeras variaciones en tonalidades o formas respecto a la imagen referencial, manteniendo siempre la cantidad, frescura, calidad y el diseño premium característico de Magia.pe® .','Rosas y arreglos','240.00','/images/pack-magia-pe-love.webp','1','1','0','https://magia.pe/products/pack-magia-pe-love');
