INSERT IGNORE INTO products (`slug`,`name`,`description`,`category`,`price`,`image`,`available`,`active`,`featured`,`source_url`) VALUES ('sunset-birthday','Sunset Birthday','Celebra un cumpleaños con un detalle lleno de color y elegancia. Este exclusivo box reúne 17 rosas color melón premium , 12 claveles blancos y un delicado mix de mini rosas naranjas y verdes de estación , creando una composición fresca, alegre y sofisticada. Incluye globo “Feliz Cumpleaños” , ideal para convertir una fecha especial en un momento más visible, más cercano y más recordado. Es un detalle pensado para quienes quieren aparecer con algo distinto y hacer que el cumpleaños se sienta realmente celebrado. Dimensiones del box: 15 cm x 15 cm (el alto puede variar según el tamaño de las flores). La frase del box puede variar según disponibilidad: “Logo Magia.pe” , “Eres Magia” o “Que tus días estén llenos de Magia.” Imagen referencial , puede presentar ligeras variaciones. Producto exclusivo de Magia.pe® — Alta Floristería con entrega el mismo día en Lima y Callao.','Regalos','325.00','/images/sunset-birthday.webp','1','1','0','https://magia.pe/products/sunset-birthday');
