INSERT IGNORE INTO site_content (`module_key`,`document`,`revision`,`updated_at`) VALUES ('experience','{\"items\": [], \"values\": {\"f1\": \"/reference/COVER-flores-amarillas-3840x1330px-7.webp\", \"f2\": \"Tu gesto en 4 pasos\", \"f3\": \"Así de fácil es crear\", \"f4\": \"Magia\", \"f5\": \"Elige pensando en esa persona\", \"f6\": \"Tú sabes qué le gusta.\", \"f7\": \"Ponle algo tuyo\", \"f8\": \"Agrega unas palabras que solo podrían venir de ti.\", \"f9\": \"Nosotros lo cuidamos\", \"f10\": \"Lo preparamos con atención y lo entregamos en el momento que elijas.\", \"f11\": \"Que lo sienta\", \"f12\": \"Hay gestos que dicen más que muchas palabras.\", \"enabled\": true}}','4','2026-10-09 15:03:51');
INSERT IGNORE INTO site_content (`module_key`,`document`,`revision`,`updated_at`) VALUES ('faq','{\"items\": [{\"id\": \"faq-1\", \"answer\": \"Entregamos en los distritos de Lima y Callao disponibles en el formulario de pedido. El costo de envío se muestra antes de confirmar.\", \"enabled\": true, \"question\": \"¿Dónde realizan entregas?\"}, {\"id\": \"faq-2\", \"answer\": \"Sí. Al completar el pedido podrás elegir una fecha desde hoy y hasta 90 días después. La entrega queda sujeta a confirmación de disponibilidad.\", \"enabled\": true, \"question\": \"¿Puedo elegir la fecha de entrega?\"}, {\"id\": \"faq-3\", \"answer\": \"Por supuesto. Escribe tu mensaje en el formulario y lo incluiremos con el regalo. Puedes usar hasta 600 caracteres.\", \"enabled\": true, \"question\": \"¿Puedo incluir una dedicatoria?\"}, {\"id\": \"faq-4\", \"answer\": \"Al registrarlo recibirás un código de pedido. Nuestro equipo revisará la disponibilidad y coordinará contigo la confirmación y el pago. Registrar un pedido no realiza un cobro automático.\", \"enabled\": true, \"question\": \"¿Cómo se confirma y paga mi pedido?\"}, {\"id\": \"faq-5\", \"answer\": \"Las imágenes son referenciales. Los colores y las flores de temporada pueden variar ligeramente; siempre respetaremos el estilo del detalle seleccionado.\", \"enabled\": true, \"question\": \"¿El arreglo será igual al de la foto?\"}], \"values\": {\"f1\": \"TE ACOMPAÑAMOS\", \"f2\": \"¿Tienes alguna duda,\", \"f3\": \"necesitas ayuda?\", \"enabled\": true}}','4','2026-10-09 15:03:51');
